#[derive(Clone,Copy,Debug,PartialEq)]
pub struct Layout {pub x:f32,pub y:f32,pub width:f32,pub height:f32,pub inset_x:bool,pub inset_y:bool,pub top:f32,pub bottom:f32}
impl Layout {
 pub fn new(w:f32,h:f32)->Self {
  let inset_x=w>=520.0;let inset_y=h>=312.0;
  let width=if inset_x{(w-100.0).min(555.0)}else{w};
  let x=((w-width)*0.5).floor();let y=if inset_y{6.0}else{0.0};let height=h-2.0*y;
  Self{x,y,width,height,inset_x,inset_y,top:y+25.0,bottom:if inset_y{y+height}else{h-5.0}}
 }
 pub fn nav_top(&self)->f32 {if self.inset_y{self.top}else{self.y+20.0}}
 pub fn list_x(&self)->f32{self.x+128.0}
 pub fn list_contains(&self,p:[f32;2])->bool{hit(p,[self.list_x(),self.top,219.0,self.bottom-self.top])}
 pub fn button(&self,n:usize)->[f32;4]{[self.x+self.width-65.0-if self.inset_x{0.0}else{5.0},self.bottom-20.0-n as f32*25.0,65.0,20.0]}
 pub fn row(&self,i:usize,scroll:f32)->[f32;4]{[self.list_x()+3.0,self.top+OPTIONS[i].y as f32-scroll,204.0,18.0]}
 pub fn max_scroll(&self)->f32{(CONTENT_HEIGHT as f32-(self.bottom-self.top)).max(0.0)}
}
pub fn hit(p:[f32;2],r:[f32;4])->bool{p[0]>=r[0]&&p[0]<r[0]+r[2]&&p[1]>=r[1]&&p[1]<r[1]+r[3]}

// Each tab owns its rows and scroll extent. Search stays within the selected tab.
pub fn page_rows(page:usize, query:&str)->Vec<usize>{
 let query=query.to_lowercase();
 OPTIONS.iter().enumerate().filter_map(|(i,o)|
  (o.page==page && (query.is_empty() || o.name.to_lowercase().contains(&query))).then_some(i)
 ).collect()
}
pub fn page_origin(page:usize)->i32{
 OPTIONS.iter().filter(|o|o.page==page).map(|o|o.y).min().unwrap_or(0)
}
pub fn page_height(page:usize)->f32{
 (OPTIONS.iter().filter(|o|o.page==page).map(|o|o.y+18).max().unwrap_or(0)-page_origin(page)).max(0) as f32
}
#[cfg(test)]
mod tab_tests {
 use super::*;
 #[test] fn tabs_partition_every_option(){
  let mut visits=vec![0;OPTIONS.len()];
  for page in 0..PAGES.len(){
   let rows=page_rows(page,"");assert!(!rows.is_empty());
   for i in rows{assert_eq!(OPTIONS[i].page,page);visits[i]+=1;}
  }
  assert!(visits.iter().all(|&n|n==1));
 }
 #[test] fn search_cannot_expose_a_different_tab(){
  for page in 0..PAGES.len(){
   for query in ["render","particle","ANIMATION","fog",""]{
    for i in page_rows(page,query){assert_eq!(OPTIONS[i].page,page);assert!(OPTIONS[i].name.to_lowercase().contains(&query.to_lowercase()));}
   }
  }
 }
 #[test] fn page_scroll_extents_cover_only_that_page(){
  for page in 0..PAGES.len(){
   let rows=page_rows(page,"");
   assert_eq!(rows.iter().map(|&i|OPTIONS[i].y-page_origin(page)).min(),Some(0));
   assert_eq!(rows.iter().map(|&i|OPTIONS[i].y+18-page_origin(page)).max().unwrap() as f32,page_height(page));
  }
 }
 #[test] fn first_category_touches_each_mod_header(){
  assert_eq!(NAV_Y[0],MOD_HEADER_Y[0]+18);
  assert_eq!(NAV_Y[3],MOD_HEADER_Y[1]+18);
  for pair in NAV_Y[..3].windows(2).chain(NAV_Y[3..].windows(2)){assert_eq!(pair[1]-pair[0],18);}
 }
}
